class Solution {
    public int influenceScore(int[] citations) {
        int[] s = citations.clone();
        Arrays.sort(s);
        int n = s.length, h = 0;
        while (h < n && s[n - 1 - h] >= h + 1) h++;
        return h;
    }
}

