static int descending(const void* a, const void* b) {
    int p = *(const int*) a, q = *(const int*) b;
    return (q > p) - (q < p);
}

int influenceScore(int* citations, int citationsSize) {
    int* s = malloc(citationsSize * sizeof(int));
    memcpy(s, citations, citationsSize * sizeof(int));
    qsort(s, citationsSize, sizeof(int), descending);
    int h = 0;
    while (h < citationsSize && s[h] >= h + 1) h++;
    free(s);
    return h;
}

