class Solution:
    def influenceScore(self, citations: List[int]) -> int:
        n = len(citations)
        bucket = [0] * (n + 1)
        for c in citations:
            bucket[min(c, n)] += 1
        at_least = 0
        for h in range(n, -1, -1):
            at_least += bucket[h]
            if at_least >= h:
                return h
        return 0

