class Solution {
    public int influenceScore(int[] citations) {
        int n = citations.length;
        int[] bucket = new int[n + 1];
        for (int c : citations) bucket[Math.min(c, n)]++;
        int atLeast = 0;
        for (int h = n; h >= 0; h--) {
            atLeast += bucket[h];
            if (atLeast >= h) return h;
        }
        return 0;
    }
}

