int influenceScore(int* citations, int citationsSize) {
    int n = citationsSize;
    int* bucket = calloc(n + 1, sizeof(int));
    for (int i = 0; i < n; i++) bucket[citations[i] < n ? citations[i] : n]++;
    int atLeast = 0, h = n;
    for (; h >= 0; h--) {
        atLeast += bucket[h];
        if (atLeast >= h) break;
    }
    free(bucket);
    return h;
}
